WITH filtered AS (SELECT *, ARRAY_CONTAINS(tags, 'sale') AS is_sale, COALESCE(brand, 'OTHER') AS resolved_brand FROM products WHERE SIZE(tags) >= 2 AND brand IS NOT DISTINCT FROM 'Initech') SELECT s.id, s.product_name, s.category, s.price, s.stock_qty, s.launch_date, s.tags, s.resolved_brand, x.order_item_quantity FROM filtered s LEFT JOIN LATERAL (SELECT c.quantity AS order_item_quantity FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) x ON TRUE
